/**
 * @param {Generator} generator
 * @return {[Function, Promise]}
 */
var cancellable = function(generator) {
    let cancel;
    // Rejects with the string "Cancelled" once cancel() is called
    const cancelPromise = new Promise((_, reject) => {
        cancel = () => reject("Cancelled");
    });
    cancelPromise.catch(() => {});   // avoid unhandled-rejection noise

    const promise = (async () => {
        let step = generator.next();          // run to the first yield
        while (!step.done) {
            let value, error, failed = false;
            try {
                // Race the yielded promise against cancellation
                value = await Promise.race([step.value, cancelPromise]);
            } catch (e) {
                failed = true;                // yielded promise rejected, or cancelled
                error = e;
            }
            // Resume the generator with the value, or throw the error into it.
            // If the generator itself throws here, the outer promise rejects.
            step = failed ? generator.throw(error) : generator.next(value);
        }
        return step.value;                    // generator finished: resolve its return value
    })();

    return [cancel, promise];
};
